/* 工具函数                                                             */
/* ------------------------------------------------------------------ */
/** 引用句 -> Markdown 行，时间戳是可点回跳的 obsidian:// 链接 */
function quoteLineFor(seg, it, feed, protocol) {
  const t = Math.max(0, Math.round(Number((seg && seg.start) || 0)));
  const stamp = Math.floor(t / 60) + ':' + String(t % 60).padStart(2, '0');
  const id = (it && it.id) || '';
  const link = 'obsidian://' + protocol + '?id=' + encodeURIComponent(id) + '&t=' + t;
  const text = String((seg && seg.text) || '').replace(/\s+/g, ' ').trim();
  const src = (feed && feed.title) || (it && it.title) || '';
  return '- [' + stamp + '](' + link + ') ' + text + (src ? ' — ' + src : '') + '\n';
}

/** 跟读门控：开关关着，或分数达到 ok 档（70）才前进 */
function shadowAdvance(score, gate) {
  return !gate || Number(score) >= 70;
}

function hash(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
  return 'h' + (h >>> 0).toString(36);
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function stripTags(s) {
  return String(s || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function fmtTime(sec) {
  sec = Math.max(0, Math.floor(sec || 0));
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = sec % 60;
  const p = (n) => String(n).padStart(2, '0');
  return h > 0 ? `${h}:${p(m)}:${p(s)}` : `${m}:${p(s)}`;
}

function parseTimeStr(v) {
  if (v == null) return 0;
  const s = String(v).trim();
  if (/^\d+$/.test(s)) return parseInt(s, 10);
  const parts = s.split(':').map((x) => parseFloat(x));
  if (parts.some((x) => isNaN(x))) return 0;
  let sec = 0;
  for (const p of parts) sec = sec * 60 + p;
  return sec;
}

/** 把一段文本切成句子（尽量不切错缩写） */
function splitSentences(text) {
  const clean = String(text || '').replace(/\r/g, '').replace(/[ \t]+/g, ' ').trim();
  if (!clean) return [];
  // 中文用 。！？；…，英文用 .!? + 空格，两种都要切（粤语语料常中英混排）
  const chunks = clean.split(/(?<=[。！？；…!?])|(?<=\.)(?=\s)|\n+/);
  const out = [];
  for (const raw of chunks) {
    const t = raw.trim();
    if (!t) continue;
    // 收尾的引号/括号跟着上一句走，别让它单独成句
    if (out.length && /^[」』”’"）)\]】]/.test(t)) {
      out[out.length - 1] += t[0];
      const rest = t.slice(1).trim();
      if (rest) out.push(rest);
      continue;
    }
    out.push(t);
  }
  // 只有极短碎片（多为切分噪声）才并回上一句，正常短句保留
  const merged = [];
  for (const t of out) {
    const prev = merged[merged.length - 1];
    if (prev && prev.length <= 2) merged[merged.length - 1] = prev + t;
    else merged.push(t);
  }
  return merged;
}

